 R19Camera CameraMetricR19(string stage,int w,int h,bool wide){var c=(Camera)Property(current,"ReviewCamera");var actor=(Transform)Field(Property(current,"ReviewCrab"),"Root");var min=new Vector3(float.PositiveInfinity,float.PositiveInfinity,0);var max=new Vector3(float.NegativeInfinity,float.NegativeInfinity,0);foreach(var rr in actor.GetComponentsInChildren<MeshRenderer>())if(rr.enabled&&rr.gameObject.activeInHierarchy){var b=rr.bounds;for(int i=0;i<8;i++){var v=c.WorldToViewportPoint(b.center+Vector3.Scale(b.extents,new Vector3((i&1)==0?-1:1,(i&2)==0?-1:1,(i&4)==0?-1:1)));min=Vector3.Min(min,v);max=Vector3.Max(max,v);}}var center=c.ViewportPointToRay(new Vector3(.5f,.5f));var edge=c.ViewportPointToRay(new Vector3(.98f,.5f));return new R19Camera{stage=stage,width=w,height=h,wide=wide,size=c.orthographicSize,lead=center.origin.x-actor.position.x,aheadWorld=edge.origin.x-actor.position.x,actorViewport=c.WorldToViewportPoint(actor.position),actorWidthPixels=(max.x-min.x)*w,actorHeightPixels=(max.y-min.y)*h};}
