 [UnityTest]public IEnumerator R19CameraPeek(){Directory.CreateDirectory(Evidence);yield return NewRetrySubject(false,true,true,true,true,true,true);var aim=JsonUtility.ToJson(new Aim{angle=15,power=57.30769f,direction=1});Call(current,"Configure",JsonUtility.ToJson(new InputSpec{angle=15,power=57.30769f,direction=1}));Call(current,"BeginAim","");Call(current,"PreviewLaunch",aim);Call(current,"BeginSpinCharge","");for(int i=0;i<601;i++){Call(current,"AddSpinWork",JsonUtility.ToJson(new Work{direction=1}));Call(current,"Tick",1f/60);}Call(current,"ReleaseLaunch",aim);for(int i=0;i<1600&&F(State(current),"worldX")<74;i++)Call(current,"Tick",1f/60);Assert.That(F(State(current),"worldX"),Is.GreaterThanOrEqualTo(74));var r=new R19RouteObservation{method="limited camera-only sample at x74 after review found next fixtures outside portrait; no new full route run"};CapturePairR19(r,"x74-peek");string body=(string)Call(WorldR18(),"LaunchBodyReceipt");Call(current,"SetReducedMotion","1");CaptureRoute("r19-camera","x74-peek-reduced");Assert.That((string)Call(WorldR18(),"LaunchBodyReceipt"),Is.EqualTo(body));Assert.That(r.cameraBodyInvariant,Is.True);r.final=JsonUtility.ToJson(State(current));File.WriteAllText(Path.Combine(Evidence,"camera-peek.json"),JsonUtility.ToJson(r,true));Call(current,"ShutdownReviewPhysics");current=null;yield return null;}
 [UnityTest]public IEnumerator R19ObserveRoute(){Directory.CreateDirectory(Evidence);var file=Path.Combine(Evidence,"route-observation.json");Assert.That(File.Exists(file),Is.False);var r=new R19RouteObservation();Action save=()=>File.WriteAllText(file,JsonUtility.ToJson(r,true));yield return NewRetrySubject(false,true,true,true,true,true,true);var aim=JsonUtility.ToJson(new Aim{angle=15,power=57.30769f,direction=1});Call(current,"Configure",JsonUtility.ToJson(new InputSpec{angle=15,power=57.30769f,direction=1}));Call(current,"BeginAim","");Call(current,"PreviewLaunch",aim);Call(current,"BeginSpinCharge","");for(int i=0;i<601;i++){Call(current,"AddSpinWork",JsonUtility.ToJson(new Work{direction=1}));Call(current,"Tick",1f/60);}Call(current,"ReleaseLaunch",aim);var sim=WorldR18();r.launch=JsonUtility.ToJson(Field(State(current),"launchReceipt"));r.panels=ObjectContractR18(ObjectPanelsR18());save();int shot=0;float last=-100;for(int i=0;i<9000&&!(bool)Property(current,"Finished");i++){Call(current,"Tick",1f/60);var state=State(current);float x=F(state,"worldX");var body=(Rigidbody)Property(sim,"Body");if(x>48&&x<101&&Mathf.Abs(x-last)>.45f){r.path.Add(new R19Path{time=F(state,"time"),x=x,y=body.position.y,vx=body.linearVelocity.x,vy=body.linearVelocity.y,spin=body.angularVelocity.magnitude/(2*Mathf.PI),com=body.worldCenterOfMass,part=(string)Field(sim,"LastPart"),surface=(string)Field(sim,"LastSurface")});last=x;}if(shot<3&&x>new[]{55,74,100}[shot]){CapturePairR19(r,"x"+new[]{55,74,100}[shot]);shot++;save();}}r.final=JsonUtility.ToJson(State(current));foreach(var e in (IEnumerable)Field(sim,"BreakEvents"))r.breaks.Add(new BreakRecord{id=(string)Field(e,"id"),material=(string)Field(e,"material"),secondary=(bool)Field(e,"secondary"),time=F(e,"time"),position=(Vector3)Field(e,"position")});save();Assert.That(r.cameraBodyInvariant,Is.True);Call(current,"ShutdownReviewPhysics");current=null;yield return null;}
